// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PENNY_BY_PENNY, LogFile} from "../src/PENNY_BY_PENNY.sol";

uint256 constant VALUE_CAP = 1000000000000000000000000000000;

contract InvMutTest is Test {
    PENNY_BY_PENNY c;
    function setUp() public { c = new PENNY_BY_PENNY(); }
    function testFuzz_property(uint256 amount, uint32 lockTime, address actor) public {
        vm.assume(amount <= VALUE_CAP);
        vm.assume(actor != address(0));
        amount = bound(amount, 0, 1e30);
        LogFile log = new LogFile();
        c.SetLogFile(address(log));
        vm.deal(actor, amount);
        vm.prank(actor);
        c.Put{value: amount}(lockTime);
        (address sender, , uint val, ) = log.History(0);
        assertTrue(sender == actor && val == amount, "Put must record the depositor and amount in the configured LogFile");
    }
}
